import datetime
from decimal import Decimal
import json
import os
import sqlite3
import sys


def load_database(dir_path):
    conn = sqlite3.connect(":memory:")
    files = {
        "calibration_log": ["calibration_log.sql", "calibration_log"],
        "lab_certificates": ["lab_certificates.sql", "lab_certificates"],
        "parts": ["parts.sql", "parts"],
        "spec_sheets": ["spec_sheets.sql", "spec_sheets"],
        "test_reports": ["test_reports.sql", "test_reports"],
    }

    dir_files = os.listdir(dir_path)
    for key, filenames in files.items():
        found_path = None
        for fname in filenames:
            p = os.path.join(dir_path, fname)
            if os.path.exists(p):
                found_path = p
                break
        if not found_path:
            for actual_name in dir_files:
                if actual_name.lower().startswith(key.lower()):
                    found_path = os.path.join(dir_path, actual_name)
                    break
        if found_path:
            with open(found_path, "r", encoding="utf-8") as f:
                content = f.read()
            conn.executescript(content)

    return conn


def get_values(conn, table, col, cmp_code, val_type):
    cur = conn.cursor()
    try:
        cur.execute(
            f"SELECT {col} FROM {table} WHERE cmp_code = ? AND {col} IS NOT NULL",
            (cmp_code,),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return set()

    formatted = set()
    for (val,) in rows:
        if val is None:
            continue
        if val_type == "date":
            dt = datetime.date(1970, 1, 1) + datetime.timedelta(days=int(val))
            formatted.add(dt.isoformat())
        elif val_type == "force_kn":
            d = Decimal(str(val)) / Decimal(100)
            s = f"{d:f}"
            if "." in s:
                s = s.rstrip("0").rstrip(".")
            formatted.add(s)
    return formatted


def resolve_fact(conn, primary_spec, fallback_spec, cmp_code, val_type):
    p_doc, p_tbl, p_col = primary_spec
    p_vals = get_values(conn, p_tbl, p_col, cmp_code, val_type)
    if len(p_vals) > 1:
        return "CONFLICT"
    elif len(p_vals) == 1:
        return [next(iter(p_vals)), p_doc]

    if fallback_spec is not None:
        f_doc, f_tbl, f_col = fallback_spec
        f_vals = get_values(conn, f_tbl, f_col, cmp_code, val_type)
        if len(f_vals) > 1:
            return "CONFLICT"
        elif len(f_vals) == 1:
            return [next(iter(f_vals)), f_doc]

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]
    conn = load_database(dir_path)

    cur = conn.cursor()
    all_codes = set()
    for tbl in [
        "component_master",
        "rig_calibration",
        "lab_cert",
        "design_spec",
        "inhouse_break_test",
    ]:
        try:
            cur.execute(f"SELECT DISTINCT cmp_code FROM {tbl} WHERE cmp_code IS NOT NULL")
            all_codes.update(row[0] for row in cur.fetchall())
        except sqlite3.OperationalError:
            pass
    cmp_codes = sorted(all_codes)

    rules = [
        (
            "ea.calibration_current",
            [
                (
                    "calibration date",
                    ("calibration_log", "rig_calibration", "rig_cal_epd"),
                    None,
                    "date",
                ),
                (
                    "test date",
                    ("test_reports", "inhouse_break_test", "inhouse_break_epd"),
                    ("lab_certificates", "lab_cert", "lab_break_epd"),
                    "date",
                ),
            ],
        ),
        (
            "ea.load_with_margin",
            [
                (
                    "measured load",
                    ("lab_certificates", "lab_cert", "lab_break_dan"),
                    ("test_reports", "inhouse_break_test", "inhouse_break_dan"),
                    "force_kn",
                ),
                (
                    "specified minimum",
                    ("spec_sheets", "design_spec", "floor_force_dan"),
                    None,
                    "force_kn",
                ),
            ],
        ),
    ]

    result = {}
    for rule_name, facts in rules:
        for code in cmp_codes:
            pair_id = f"{rule_name}::{code}"
            pair_data = {}
            for fact_name, primary_spec, fallback_spec, val_type in facts:
                pair_data[fact_name] = resolve_fact(
                    conn, primary_spec, fallback_spec, code, val_type
                )
            result[pair_id] = pair_data

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
