import sys
import os
import json
from decimal import Decimal


def parse_edi_loops(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    segments = [s.strip() for s in content.split('~') if s.strip()]
    loops = []
    current_loop = None
    for seg in segments:
        parts = seg.split('*')
        tag = parts[0]
        if tag == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            if tag in ('CTT', 'SE', 'GE', 'IEA'):
                loops.append(current_loop)
                current_loop = None
            else:
                current_loop.append(parts)
    if current_loop is not None:
        loops.append(current_loop)
    return loops


def format_decimal(d: Decimal) -> str:
    s = f"{d:f}"
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s


def parse_load_kn(val_str: str, unit: str) -> Decimal:
    val = Decimal(val_str)
    unit = unit.upper()
    if unit == 'KN':
        return val
    elif unit == 'NT':
        return val / Decimal(1000)
    return val


def parse_date_d8(d8_str: str) -> str:
    return f"{d8_str[:4]}-{d8_str[4:6]}-{d8_str[6:8]}"


def extract_data_by_doc(directory):
    files = {
        'calibration_log': os.path.join(directory, 'calibration_log.edi'),
        'lab_certificates': os.path.join(directory, 'lab_certificates.edi'),
        'parts': os.path.join(directory, 'parts.edi'),
        'spec_sheets': os.path.join(directory, 'spec_sheets.edi'),
        'test_reports': os.path.join(directory, 'test_reports.edi')
    }

    doc_data = {doc: {} for doc in files}
    all_parts = set()

    for doc_name, filepath in files.items():
        loops = parse_edi_loops(filepath)
        for loop in loops:
            part_key = None
            for seg in loop:
                if seg[0] == 'LIN' and len(seg) > 3 and seg[2] == 'BP':
                    part_key = seg[3]
                    break
            if not part_key:
                continue

            all_parts.add(part_key)
            if part_key not in doc_data[doc_name]:
                doc_data[doc_name][part_key] = []

            loop_info = {}
            for seg in loop:
                tag = seg[0]
                if tag == 'DTP' and len(seg) > 3 and seg[2] == 'D8':
                    loop_info[f"DTP_{seg[1]}"] = parse_date_d8(seg[3])
                elif tag == 'MEA' and len(seg) > 4:
                    loop_info[f"MEA_{seg[2]}"] = parse_load_kn(seg[3], seg[4])

            doc_data[doc_name][part_key].append(loop_info)

    return doc_data, sorted(all_parts)


def resolve_fact(doc_data, primary_doc, fallback_doc, part, key_type, key_name):
    for doc in ([primary_doc] if primary_doc else []) + ([fallback_doc] if fallback_doc else []):
        loops = doc_data.get(doc, {}).get(part, [])
        values = []
        for loop in loops:
            if key_name in loop:
                val = loop[key_name]
                if val not in values:
                    values.append(val)

        if len(values) == 1:
            val = values[0]
            if key_type == 'load':
                formatted = format_decimal(val)
            else:
                formatted = str(val)
            return [formatted, doc]
        elif len(values) > 1:
            return "CONFLICT"

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    directory = sys.argv[1]
    doc_data, all_parts = extract_data_by_doc(directory)

    rules = [
        ("ea.calibration_current", [
            ("calibration date", 'date', 'calibration_log', None, 'DTP_300'),
            ("test date", 'date', 'test_reports', 'lab_certificates', 'DTP_301', 'DTP_302')
        ]),
        ("ea.load_with_margin", [
            ("measured load", 'load', 'lab_certificates', 'test_reports', 'MEA_UFL', 'MEA_UFH'),
            ("specified minimum", 'load', 'spec_sheets', None, 'MEA_UFM')
        ])
    ]

    result = {}

    for rule_name, facts in rules:
        for part in all_parts:
            pair_id = f"{rule_name}::{part}"
            rule_res = {}

            for fact_info in facts:
                fact_name = fact_info[0]
                key_type = fact_info[1]
                primary_doc = fact_info[2]
                fallback_doc = fact_info[3]
                primary_key = fact_info[4]
                fallback_key = fact_info[5] if len(fact_info) > 5 else primary_key

                # Resolve with primary doc
                loops_pri = doc_data.get(primary_doc, {}).get(part, []) if primary_doc else []
                pri_vals = []
                for loop in loops_pri:
                    if primary_key in loop:
                        v = loop[primary_key]
                        if v not in pri_vals:
                            pri_vals.append(v)

                if len(pri_vals) == 1:
                    val_str = format_decimal(pri_vals[0]) if key_type == 'load' else str(pri_vals[0])
                    rule_res[fact_name] = [val_str, primary_doc]
                elif len(pri_vals) > 1:
                    rule_res[fact_name] = "CONFLICT"
                else:
                    # Check fallback
                    if fallback_doc:
                        loops_fb = doc_data.get(fallback_doc, {}).get(part, [])
                        fb_vals = []
                        for loop in loops_fb:
                            if fallback_key in loop:
                                v = loop[fallback_key]
                                if v not in fb_vals:
                                    fb_vals.append(v)
                        if len(fb_vals) == 1:
                            val_str = format_decimal(fb_vals[0]) if key_type == 'load' else str(fb_vals[0])
                            rule_res[fact_name] = [val_str, fallback_doc]
                        elif len(fb_vals) > 1:
                            rule_res[fact_name] = "CONFLICT"
                        else:
                            rule_res[fact_name] = "ABSENT"
                    else:
                        rule_res[fact_name] = "ABSENT"

            result[pair_id] = rule_res

    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()
