import sys
import os
import json
from decimal import Decimal
from collections import defaultdict


def parse_edi_loops(filepath):
    if not os.path.isfile(filepath):
        return []

    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = [seg.strip() for seg in content.split('~') if seg.strip()]
    loops = []
    current_loop = None

    for seg in segments:
        tokens = [t.strip() for t in seg.split('*')]
        if not tokens or not tokens[0]:
            continue
        seg_id = tokens[0]
        if seg_id == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            if seg_id in ('CTT', 'SE', 'GE', 'IEA'):
                loops.append(current_loop)
                current_loop = None
            else:
                current_loop.append(tokens)

    if current_loop is not None:
        loops.append(current_loop)

    return loops


def get_part_id(loop):
    for tokens in loop:
        if tokens[0] == 'LIN':
            for i in range(1, len(tokens) - 1):
                if tokens[i] == 'BP':
                    return tokens[i + 1]
    return None


def format_date(d_str):
    d_str = d_str.strip()
    if len(d_str) == 8 and d_str.isdigit():
        return f"{d_str[:4]}-{d_str[4:6]}-{d_str[6:8]}"
    return d_str


def format_kn(val_str, unit_str):
    val = Decimal(val_str)
    unit = unit_str.upper().strip()
    if unit == 'NT':
        val = val / Decimal(1000)
    elif unit == 'KN':
        pass
    s = f"{val:f}"
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s


def find_file(directory, base_name):
    for fname in [f"{base_name}.edi", base_name]:
        p = os.path.join(directory, fname)
        if os.path.isfile(p):
            return p
    return os.path.join(directory, f"{base_name}.edi")


def extract_calibration_date(loop):
    for tokens in loop:
        if tokens[0] == 'DTP' and len(tokens) >= 4:
            if tokens[1] == '300' and tokens[2] == 'D8':
                return format_date(tokens[3])
    return None


def extract_test_date_internal(loop):
    for tokens in loop:
        if tokens[0] == 'DTP' and len(tokens) >= 4:
            if tokens[1] == '301' and tokens[2] == 'D8':
                return format_date(tokens[3])
    return None


def extract_test_date_lab(loop):
    for tokens in loop:
        if tokens[0] == 'DTP' and len(tokens) >= 4:
            if tokens[1] == '302' and tokens[2] == 'D8':
                return format_date(tokens[3])
    return None


def extract_measured_load_lab(loop):
    for tokens in loop:
        if tokens[0] == 'MEA' and len(tokens) >= 5:
            if tokens[1] == 'TE' and tokens[2] == 'UFL':
                return format_kn(tokens[3], tokens[4])
    return None


def extract_measured_load_internal(loop):
    for tokens in loop:
        if tokens[0] == 'MEA' and len(tokens) >= 5:
            if tokens[1] == 'TE' and tokens[2] == 'UFH':
                return format_kn(tokens[3], tokens[4])
    return None


def extract_specified_minimum(loop):
    for tokens in loop:
        if tokens[0] == 'MEA' and len(tokens) >= 5:
            if tokens[1] == 'TE' and tokens[2] == 'UFM':
                return format_kn(tokens[3], tokens[4])
    return None


def collect_document_data(filepath, extract_fn):
    loops = parse_edi_loops(filepath)
    data = defaultdict(list)
    for loop in loops:
        part_id = get_part_id(loop)
        if not part_id:
            continue
        val = extract_fn(loop)
        if val is not None:
            data[part_id].append(val)
    return data


def resolve_fact(part_id, chain):
    for doc_name, doc_data in chain:
        vals = doc_data.get(part_id, [])
        if not vals:
            continue
        unique_vals = list(dict.fromkeys(vals))
        if len(unique_vals) == 1:
            return [unique_vals[0], doc_name]
        else:
            return "CONFLICT"
    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    doc_files = {
        'calibration_log': find_file(dir_path, 'calibration_log'),
        'lab_certificates': find_file(dir_path, 'lab_certificates'),
        'parts': find_file(dir_path, 'parts'),
        'spec_sheets': find_file(dir_path, 'spec_sheets'),
        'test_reports': find_file(dir_path, 'test_reports'),
    }

    # Discover all part IDs across files
    all_parts = set()
    for doc_name, fpath in doc_files.items():
        loops = parse_edi_loops(fpath)
        for loop in loops:
            pid = get_part_id(loop)
            if pid:
                all_parts.add(pid)

    sorted_parts = sorted(all_parts)

    # Extract datasets
    cal_date_data = collect_document_data(doc_files['calibration_log'], extract_calibration_date)
    test_date_internal = collect_document_data(doc_files['test_reports'], extract_test_date_internal)
    test_date_lab = collect_document_data(doc_files['lab_certificates'], extract_test_date_lab)

    load_lab = collect_document_data(doc_files['lab_certificates'], extract_measured_load_lab)
    load_internal = collect_document_data(doc_files['test_reports'], extract_measured_load_internal)
    spec_min_data = collect_document_data(doc_files['spec_sheets'], extract_specified_minimum)

    result = {}

    # Rule: ea.calibration_current
    for pid in sorted_parts:
        pair_id = f"ea.calibration_current::{pid}"
        cal_val = resolve_fact(pid, [('calibration_log', cal_date_data)])
        test_val = resolve_fact(pid, [
            ('test_reports', test_date_internal),
            ('lab_certificates', test_date_lab)
        ])
        result[pair_id] = {
            "calibration date": cal_val,
            "test date": test_val
        }

    # Rule: ea.load_with_margin
    for pid in sorted_parts:
        pair_id = f"ea.load_with_margin::{pid}"
        meas_val = resolve_fact(pid, [
            ('lab_certificates', load_lab),
            ('test_reports', load_internal)
        ])
        spec_val = resolve_fact(pid, [('spec_sheets', spec_min_data)])
        result[pair_id] = {
            "measured load": meas_val,
            "specified minimum": spec_val
        }

    print(json.dumps(result, indent=2))


if __name__ == '__main__':
    main()
