import sys
import os
import json
import re
from decimal import Decimal

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

def find_file(dir_path, base_name):
    for name in [f"{base_name}.txt", base_name]:
        p = os.path.join(dir_path, name)
        if os.path.exists(p):
            return p
    return None

def parse_messages(file_path):
    if not file_path or not os.path.exists(file_path):
        return []
    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
        text = f.read()

    text = text.replace('\r\n', '\n').replace('\r', '\n')
    chunks = re.split(r'={10,}', text)

    parsed = []
    for chunk in chunks:
        chunk = chunk.strip()
        if not chunk:
            continue
        parts = chunk.split('\n\n', 1)
        if len(parts) == 2:
            header, body = parts
        else:
            header, body = "", parts[0]

        part_match = re.search(r'\b(P-\d+)\b', chunk)
        if not part_match:
            continue
        part_id = part_match.group(1)
        parsed.append({
            'part_id': part_id,
            'header': header,
            'body': body
        })
    return parsed

def extract_date(body):
    # ISO date
    m_iso = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', body)
    if m_iso:
        return f"{int(m_iso.group(1)):04d}-{int(m_iso.group(2)):02d}-{int(m_iso.group(3)):02d}"

    # Month Day, Year (e.g. February 8th, 2026 or May 10th, 2026)
    for m in re.finditer(r'\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b', body):
        w = m.group(1).lower()
        if w in MONTHS:
            month = MONTHS[w]
            day = int(m.group(2))
            year = int(m.group(3))
            return f"{year:04d}-{month:02d}-{day:02d}"

    # Day Month Year (e.g. 28th Apr 2026 or 4th Jun 2026)
    for m in re.finditer(r'\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+),?\s+(\d{4})\b', body):
        w = m.group(2).lower()
        if w in MONTHS:
            month = MONTHS[w]
            day = int(m.group(1))
            year = int(m.group(3))
            return f"{year:04d}-{month:02d}-{day:02d}"

    return None

def normalize_amount(s):
    d = Decimal(s)
    if d == int(d):
        return str(int(d))
    return f"{d:f}".rstrip('0').rstrip('.')

def extract_load(body):
    matches = re.findall(r'(\d+(?:\.\d+)?)\s*(?:kN|kilonewtons)\b', body, re.IGNORECASE)
    if matches:
        return normalize_amount(matches[0])
    return None

def resolve_fact(part_id, primary_doc, fallback_doc, doc_store, fact_name):
    primary_values = doc_store.get(primary_doc, {}).get(fact_name, {}).get(part_id, [])
    if primary_values:
        unique_vals = list(set(primary_values))
        if len(unique_vals) == 1:
            return [unique_vals[0], primary_doc]
        else:
            return "CONFLICT"

    if fallback_doc:
        fallback_values = doc_store.get(fallback_doc, {}).get(fact_name, {}).get(part_id, [])
        if fallback_values:
            unique_vals = list(set(fallback_values))
            if len(unique_vals) == 1:
                return [unique_vals[0], fallback_doc]
            else:
                return "CONFLICT"

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    # Collect all part IDs across files
    all_part_ids = set()
    for fname in os.listdir(dir_path):
        fpath = os.path.join(dir_path, fname)
        if os.path.isfile(fpath):
            with open(fpath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                matches = re.findall(r'\b(P-\d+)\b', content)
                all_part_ids.update(matches)

    sorted_parts = sorted(all_part_ids, key=lambda x: (int(x.split('-')[1]) if x.split('-')[1].isdigit() else x))

    doc_store = {
        'calibration_log': {'calibration date': {}},
        'test_reports': {'test date': {}, 'measured load': {}},
        'lab_certificates': {'test date': {}, 'measured load': {}},
        'spec_sheets': {'specified minimum': {}}
    }

    # Parse calibration_log
    cal_file = find_file(dir_path, 'calibration_log')
    for msg in parse_messages(cal_file):
        pid = msg['part_id']
        d = extract_date(msg['body'])
        if d:
            doc_store['calibration_log']['calibration date'].setdefault(pid, []).append(d)

    # Parse test_reports
    tr_file = find_file(dir_path, 'test_reports')
    for msg in parse_messages(tr_file):
        pid = msg['part_id']
        d = extract_date(msg['body'])
        if d:
            doc_store['test_reports']['test date'].setdefault(pid, []).append(d)
        ld = extract_load(msg['body'])
        if ld:
            doc_store['test_reports']['measured load'].setdefault(pid, []).append(ld)

    # Parse lab_certificates
    lc_file = find_file(dir_path, 'lab_certificates')
    for msg in parse_messages(lc_file):
        pid = msg['part_id']
        d = extract_date(msg['body'])
        if d:
            doc_store['lab_certificates']['test date'].setdefault(pid, []).append(d)
        ld = extract_load(msg['body'])
        if ld:
            doc_store['lab_certificates']['measured load'].setdefault(pid, []).append(ld)

    # Parse spec_sheets
    ss_file = find_file(dir_path, 'spec_sheets')
    for msg in parse_messages(ss_file):
        pid = msg['part_id']
        ld = extract_load(msg['body'])
        if ld:
            doc_store['spec_sheets']['specified minimum'].setdefault(pid, []).append(ld)

    result = {}

    for pid in sorted_parts:
        pair_id = f"ea.calibration_current::{pid}"
        result[pair_id] = {
