import sys
import os
import json
import re
from datetime import date, timedelta
from decimal import Decimal

def parse_iso_week(s):
    s = s.strip()
    m = re.match(r'^(\d{4})-W(\d{2})-(\d)$', s)
    if not m:
        return s
    year, week, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
    try:
        return date.fromisocalendar(year, week, day).strftime('%Y-%m-%d')
    except AttributeError:
        jan4 = date(year, 1, 4)
        start_week1 = jan4 - timedelta(days=jan4.isoweekday() - 1)
        target = start_week1 + timedelta(weeks=week - 1, days=day - 1)
        return target.strftime('%Y-%m-%d')

def parse_crosstab_tsv(filepath):
    if not os.path.isfile(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.rstrip('\r\n') for line in f]

    data_lines = [l for l in lines if l.strip() and not l.startswith('#')]
    if not data_lines:
        return []

    header = data_lines[0].split('\t')
    num_records = len(header) - 1
    records = [{} for _ in range(num_records)]

    for line in data_lines[1:]:
        parts = line.split('\t')
        attr = parts[0].strip()
        for i in range(1, len(parts)):
            if i - 1 < len(records):
                records[i - 1][attr] = parts[i].strip()

    return records

def get_unique_value(raw_values, is_date):
    if is_date:
        parsed = [parse_iso_week(v) for v in raw_values]
        unique = list(dict.fromkeys(parsed))
        if len(unique) > 1:
            return "CONFLICT"
        return unique[0]
    else:
        try:
            dec_map = {}
            for v in raw_values:
                d = Decimal(v)
                if d not in dec_map:
                    dec_map[d] = v
            if len(dec_map) > 1:
                return "CONFLICT"
            return list(dec_map.values())[0]
        except Exception:
            unique = list(dict.fromkeys(raw_values))
            if len(unique) > 1:
                return "CONFLICT"
            return unique[0]

def resolve_fact(docs, entity, fact_sources, is_date):
    for doc_name, attr_name in fact_sources:
        records = docs.get(doc_name, [])
        entity_recs = [r for r in records if r.get('component.key') == entity]
        raw_values = [
            r[attr_name] for r in entity_recs
            if attr_name in r and r[attr_name] != '~' and r[attr_name].strip() != ''
        ]
        if not raw_values:
            continue
        val = get_unique_value(raw_values, is_date)
        if val == "CONFLICT":
            return "CONFLICT"
        return [val, doc_name]
    return "ABSENT"

def find_file(dir_path, base_name):
    for ext in ['.tsv', '']:
        p = os.path.join(dir_path, base_name + ext)
        if os.path.isfile(p):
            return p
    return os.path.join(dir_path, base_name + '.tsv')

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    doc_names = ['calibration_log', 'lab_certificates', 'parts', 'spec_sheets', 'test_reports']
    docs = {}
    for name in doc_names:
        fp = find_file(dir_path, name)
        docs[name] = parse_crosstab_tsv(fp)

    entities = set()
    for recs in docs.values():
        for r in recs:
            k = r.get('component.key')
            if k and k != '~':
                entities.add(k)
    sorted_entities = sorted(entities)

    rules = [
        (
            'ea.calibration_current',
            [
                ('calibration date', [('calibration_log', 'rig.cal.wk')], True),
                ('test date', [('test_reports', 'inhouse.break.wk'), ('lab_certificates', 'lab.break.wk')], True)
            ]
        ),
        (
            'ea.load_with_margin',
            [
                ('measured load', [('lab_certificates', 'lab.break.kn'), ('test_reports', 'inhouse.break.kn')], False),
                ('specified minimum', [('spec_sheets', 'floor.force.kn')], False)
            ]
        )
    ]

    result = {}
    for rule_id, fact_defs in rules:
        for entity in sorted_entities:
            pair_id = f"{rule_id}::{entity}"
            pair_facts = {}
            for fact_name, sources, is_date in fact_defs:
                pair_facts[fact_name] = resolve_fact(docs, entity, sources, is_date)
            result[pair_id] = pair_facts

    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
