    "lab_certificates": "lab_certificates.tsv",
    "parts": "parts.tsv",
    "spec_sheets": "spec_sheets.tsv",
    "test_reports": "test_reports.tsv",
}

RULES = {
    "ea.calibration_current": {
        "calibration date": {
            "primary": ("calibration_log", "rig.cal.wk", "date"),
            "fallback": None,
        },
        "test date": {
            "primary": ("test_reports", "inhouse.break.wk", "date"),
            "fallback": ("lab_certificates", "lab.break.wk", "date"),
        },
    },
    "ea.load_with_margin": {
        "measured load": {
            "primary": ("lab_certificates", "lab.break.kn", "decimal"),
            "fallback": ("test_reports", "inhouse.break.kn", "decimal"),
        },
        "specified minimum": {
            "primary": ("spec_sheets", "floor.force.kn", "decimal"),
            "fallback": None,
        },
    },
}


def load_tsv(filepath):
    if not os.path.exists(filepath):
        return {}
    rows = {}
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\r\n")
            if not line or line.startswith("#"):
                continue
            parts = [p.strip() for p in line.split("\t")]
            if parts:
                rows[parts[0]] = parts[1:]
    return rows


def parse_value(val_str, val_type):
    if val_type == "date":
        m = re.match(r"^(\d{4})-W(\d{1,2})-([1-7])$", val_str)
        if m:
            y, w, d = map(int, m.groups())
            if hasattr(datetime.date, "fromisocalendar"):
                dt = datetime.date.fromisocalendar(y, w, d)
            else:
                dt = datetime.datetime.strptime(f"{y}-W{w:02d}-{d}", "%G-W%V-%u").date()
            return dt.isoformat()
        return val_str
    elif val_type == "decimal":
        d = Decimal(val_str)
        if d == d.to_integral():
            return str(d.quantize(Decimal(1)))
        else:
            return format(d, "f").rstrip("0").rstrip(".")
    return val_str


def get_entity_values(doc_data, attr_name, entity_key):
    if "component.key" not in doc_data or attr_name not in doc_data:
        return []
    keys = doc_data["component.key"]
    attrs = doc_data[attr_name]
    vals = []
    for i, k in enumerate(keys):
        if k == entity_key and i < len(attrs):
            v = attrs[i]
            if v != "~" and v != "":
                vals.append(v)
    return vals


def get_fact_from_doc(doc_name, attr_name, val_type, entity, docs):
    raw_vals = get_entity_values(docs.get(doc_name, {}), attr_name, entity)
    if not raw_vals:
        return None
    parsed_vals = [parse_value(v, val_type) for v in raw_vals]
    unique_vals = list(dict.fromkeys(parsed_vals))
    if len(unique_vals) > 1:
        return "CONFLICT"
    return unique_vals[0]


def evaluate_fact(entity, primary_spec, fallback_spec, docs):
    primary_doc, primary_attr, val_type = primary_spec
    res = get_fact_from_doc(primary_doc, primary_attr, val_type, entity, docs)
    if res == "CONFLICT":
        return "CONFLICT"
    if res is not None:
        return [res, primary_doc]

    if fallback_spec:
        fb_doc, fb_attr, fb_val_type = fallback_spec
        res = get_fact_from_doc(fb_doc, fb_attr, fb_val_type, entity, docs)
        if res == "CONFLICT":
            return "CONFLICT"
        if res is not None:
            return [res, fb_doc]

    return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    docs = {}
    for doc_name, filename in DOC_FILES.items():
        filepath = os.path.join(dir_path, filename)
        docs[doc_name] = load_tsv(filepath)

    output = {}
    for pair in PAIRS:
        rule_name, entity = pair.split("::")
        fact_defs = RULES[rule_name]
        pair_result = {}
        for fact_name, specs in fact_defs.items():
            pair_result[fact_name] = evaluate_fact(
                entity, specs["primary"], specs["fallback"], docs
            )
        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
