    if len(parts) == 3:
        mm, dd, yyyy = parts
        return f"{int(yyyy):04d}-{int(mm):02d}-{int(dd):02d}"
    return val_str


def parse_force_kn(force_str, uom_str):
    if not force_str or not force_str.strip():
        return None
    force_str = force_str.strip()
    uom = (uom_str or "").strip().upper()
    try:
        d = Decimal(force_str)
    except Exception:
        return None
    if uom == "N":
        d = d / Decimal("1000")
    elif uom == "KN":
