import sys
import os
import json
from decimal import Decimal

def format_decimal(d: Decimal) -> str:
    if d == d.to_integral():
        return str(d.to_integral())
    s = format(d.normalize(), 'f')
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s

def format_date(d_str: str) -> str:
    parts = d_str.strip().split('/')
    if len(parts) == 3:
        m, d, y = parts
        return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
    return d_str.strip()

def find_file(dir_path, base_name):
    for name in [f"{base_name}.txt", base_name]:
        p = os.path.join(dir_path, name)
        if os.path.exists(p):
            return p
    return None

def parse_pipe_file(filepath):
    if not filepath or not os.path.exists(filepath):
        return []
    rows = []
    headers = None
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = [p.strip() for p in line.split('|')]
            if headers is None:
                headers = parts
            else:
                row = dict(zip(headers, parts))
                rows.append(row)
    return rows

def extract_date(row, col_name):
    raw = row.get(col_name, '').strip()
    if not raw:
        return None
    try:
        return format_date(raw)
    except Exception:
        return None

def extract_force_kn(row, force_col, uom_col):
    raw_force = row.get(force_col, '').strip()
    raw_uom = row.get(uom_col, '').strip().upper()
    if not raw_force or not raw_uom:
        return None
    try:
        d = Decimal(raw_force)
        if raw_uom == 'KN':
            pass
        elif raw_uom == 'N':
            d = d / Decimal('1000')
        else:
            return None
        return format_decimal(d)
    except Exception:
        return None

def resolve_fact(entity, primary_doc, primary_rows, extract_fn, fallback_doc=None, fallback_rows=None):
    primary_vals = []
    for r in primary_rows:
        if r.get('COMPONENT_CATALOG_KEY') == entity:
            val = extract_fn(r)
            if val is not None:
                primary_vals.append(val)

    if primary_vals:
        unique_vals = list(set(primary_vals))
        if len(unique_vals) > 1:
            return "CONFLICT"
        return [unique_vals[0], primary_doc]

    if fallback_doc and fallback_rows is not None:
        fallback_vals = []
        for r in fallback_rows:
            if r.get('COMPONENT_CATALOG_KEY') == entity:
                val = extract_fn(r)
                if val is not None:
                    fallback_vals.append(val)
        if fallback_vals:
            unique_vals = list(set(fallback_vals))
            if len(unique_vals) > 1:
                return "CONFLICT"
            return [unique_vals[0], fallback_doc]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    doc_names = [
        'calibration_log',
        'lab_certificates',
        'parts',
        'spec_sheets',
        'test_reports'
    ]

    docs = {}
    all_keys = set()
    for name in doc_names:
        filepath = find_file(dir_path, name)
        rows = parse_pipe_file(filepath)
        docs[name] = rows
        for r in rows:
            k = r.get('COMPONENT_CATALOG_KEY')
            if k:
                all_keys.add(k)

    sorted_keys = sorted(all_keys)

    rules = ['ea.calibration_current', 'ea.load_with_margin']
    pairs = []
    for r in rules:
        for k in sorted_keys:
            pairs.append(f"{r}::{k}")

    output = {}

    for pair_id in pairs:
        rule_name, entity = pair_id.split('::', 1)
        if rule_name == 'ea.calibration_current':
            cal_date = resolve_fact(
                entity,
                'calibration_log',
                docs['calibration_log'],
                lambda r: extract_date(r, 'LOAD_FRAME_CAL_DAY')
            )
            test_date = resolve_fact(
                entity,
                'test_reports',
                docs['test_reports'],
                lambda r: extract_date(r, 'INTERNAL_TRIAL_DAY'),
                'lab_certificates',
                docs['lab_certificates'],
                lambda r: extract_date(r, 'ACCREDITED_TRIAL_DAY')
            )
            output[pair_id] = {
                "calibration date": cal_date,
                "test date": test_date
            }
        elif rule_name == 'ea.load_with_margin':
            meas_load = resolve_fact(
                entity,
                'lab_certificates',
                docs['lab_certificates'],
                lambda r: extract_force_kn(r, 'ACCREDITED_ULTIMATE_FORCE', 'ACCREDITED_ULTIMATE_FORCE_UOM'),
                'test_reports',
                docs['test_reports'],
                lambda r: extract_force_kn(r, 'INTERNAL_ULTIMATE_FORCE', 'INTERNAL_ULTIMATE_FORCE_UOM')
            )
            spec_min = resolve_fact(
                entity,
                'spec_sheets',
                docs['spec_sheets'],
                lambda r: extract_force_kn(r, 'REQUIRED_ULTIMATE_FORCE', 'REQUIRED_ULTIMATE_FORCE_UOM')
            )
            output[pair_id] = {
                "measured load": meas_load,
                "specified minimum": spec_min
            }

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
