import sys
import os
import json
import sqlite3
import datetime
from decimal import Decimal

def load_sql_file(dir_path, base_name):
    for name in [f"{base_name}.sql", base_name]:
        p = os.path.join(dir_path, name)
        if os.path.exists(p):
            with open(p, 'r', encoding='utf-8') as f:
                content = f.read()
            conn = sqlite3.connect(':memory:')
            conn.executescript(content)
            return conn
    return None

def inspect_table(conn):
    if conn is None:
        return None, []
    cursor = conn.cursor()
    cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
    tables = [row[0] for row in cursor.fetchall()]
    if not tables:
        return None, []
    table = tables[0]
    cursor.execute(f"PRAGMA table_info({table})")
    cols = [row[1] for row in cursor.fetchall()]
    return table, cols

def epd_to_date(epd_val):
    d = datetime.date(1970, 1, 1) + datetime.timedelta(days=int(epd_val))
    return d.isoformat()

def dan_to_kn(dan_val):
    d = Decimal(str(dan_val)) / Decimal(100)
    normalized = d.normalize()
    sign, digits, exponent = normalized.as_tuple()
    if exponent > 0:
        return str(int(normalized))
    return f"{normalized:f}"

def evaluate_fact(entity, primary_info, fallback_info, val_type):
    for info in [primary_info, fallback_info]:
        if not info:
            continue
        conn, table, cmp_col, val_col, doc_name = info
        if not conn or not table or not val_col:
            continue
        cursor = conn.cursor()
        cursor.execute(f"SELECT {val_col} FROM {table} WHERE {cmp_col} = ?", (entity,))
        rows = cursor.fetchall()
        non_null_rows = [r[0] for r in rows if r[0] is not None]
        if not non_null_rows:
            continue

        if val_type == 'date':
            distinct = set(int(v) for v in non_null_rows)
        elif val_type == 'load_kn':
            distinct = set(Decimal(str(v)) for v in non_null_rows)
        else:
            distinct = set(non_null_rows)

        if len(distinct) > 1:
            return "CONFLICT"
        else:
            v = next(iter(distinct))
            if val_type == 'date':
                formatted = epd_to_date(v)
            elif val_type == 'load_kn':
                formatted = dan_to_kn(v)
            else:
                formatted = str(v)
            return [formatted, doc_name]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    doc_names = ['calibration_log', 'lab_certificates', 'parts', 'spec_sheets', 'test_reports']
    conns = {name: load_sql_file(dir_path, name) for name in doc_names}

    infos = {}
    entities = set()

    for name, conn in conns.items():
        if not conn:
            continue
        table, cols = inspect_table(conn)
        cmp_col = next((c for c in cols if 'cmp' in c or 'code' in c or 'part' in c), None)
        if cmp_col:
            cursor = conn.cursor()
            cursor.execute(f"SELECT DISTINCT {cmp_col} FROM {table} WHERE {cmp_col} IS NOT NULL")
            for r in cursor.fetchall():
                entities.add(r[0])
        infos[name] = {
            'conn': conn,
            'table': table,
            'cols': cols,
            'cmp_col': cmp_col
        }

    def make_doc_info(doc_name, col_filter):
        inf = infos.get(doc_name)
        if not inf or not inf['conn']:
            return None
        col = next((c for c in inf['cols'] if col_filter(c)), None)
        if not col:
            return None
        return (inf['conn'], inf['table'], inf['cmp_col'], col, doc_name)

    cal_log_epd = make_doc_info('calibration_log', lambda c: 'cal' in c or 'epd' in c)
    test_rep_epd = make_doc_info('test_reports', lambda c: c.endswith('_epd'))
    lab_cert_epd = make_doc_info('lab_certificates', lambda c: c.endswith('_epd'))

    lab_cert_dan = make_doc_info('lab_certificates', lambda c: c.endswith('_dan'))
    test_rep_dan = make_doc_info('test_reports', lambda c: c.endswith('_dan'))
    spec_sheet_dan = make_doc_info('spec_sheets', lambda c: c.endswith('_dan'))

    rules = [
        (
            'ea.calibration_current',
            [
                ('calibration date', cal_log_epd, None, 'date'),
                ('test date', test_rep_epd, lab_cert_epd, 'date'),
            ]
        ),
        (
            'ea.load_with_margin',
            [
                ('measured load', lab_cert_dan, test_rep_dan, 'load_kn'),
                ('specified minimum', spec_sheet_dan, None, 'load_kn'),
            ]
        )
    ]

    sorted_entities = sorted(entities)
    output = {}

    for rule_id, facts in rules:
        for entity in sorted_entities:
            pair_id = f"{rule_id}::{entity}"
            pair_dict = {}
            for fact_name, primary_info, fallback_info, val_type in facts:
                pair_dict[fact_name] = evaluate_fact(entity, primary_info, fallback_info, val_type)
            output[pair_id] = pair_dict

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
