def parse_edi_loops(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    segments = [s.strip() for s in content.split('~') if s.strip()]
    loops = []
    current_loop = None

    for seg in segments:
        parts = seg.split('*')
        seg_id = parts[0]
        if seg_id == 'LX':
            if current_loop is not None:
                loops.append(current_loop)
            current_loop = []
        elif current_loop is not None:
            current_loop.append(parts)

    if current_loop is not None:
        loops.append(current_loop)

    return loops


def get_loop_entity(loop_segments):
    for parts in loop_segments:
        if parts[0] == 'LIN':
            for i, p in enumerate(parts):
                if p == 'BP' and i + 1 < len(parts):
                    return parts[i + 1]
    return None


def format_decimal(d: Decimal) -> str:
    s = f"{d:f}"
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    return s


def convert_force_to_kn(val_str, unit):
    val = Decimal(val_str)
    unit_upper = unit.upper()
    if unit_upper == 'NT':
        val = val / Decimal(1000)
    elif unit_upper == 'KN':
        val = val
    return format_decimal(val)


def format_date(d_str):
    d_clean = d_str.strip()
    if len(d_clean) == 8 and d_clean.isdigit():
        return f"{d_clean[:4]}-{d_clean[4:6]}-{d_clean[6:8]}"
    return d_clean


def resolve_fact(primary_doc, primary_vals, fallback_doc=None, fallback_vals=None):
    if primary_vals:
        unique_vals = list(dict.fromkeys(primary_vals))
        if len(unique_vals) > 1:
            return "CONFLICT"
        return [unique_vals[0], primary_doc]

    if fallback_doc and fallback_vals:
        unique_vals = list(dict.fromkeys(fallback_vals))
        if len(unique_vals) > 1:
            return "CONFLICT"
        return [unique_vals[0], fallback_doc]

    return "ABSENT"


def main():
