                    lab_test_dates[ent].append(format_date(seg[3]))
                elif seg[0] == 'MEA' and len(seg) >= 5 and seg[1] == 'TE' and seg[2] == 'UFL':
                    lab_measured_loads[ent].append(convert_force_to_kn(seg[3], seg[4]))

    for loop in parts_loops:
