def parse_and_convert_load(val_str: str, unit_str: str) -> str:
    val = Decimal(val_str.strip())
    unit = unit_str.strip().upper()
    if unit == "NT":
        val = val / Decimal(1000)
    elif unit == "KN":
        pass

    if val == val.to_integral():
        return str(val.to_integral())
    else:
        return f"{val:f}".rstrip("0").rstrip(".")


def parse_edi_loops(filepath: str):
    if not os.path.exists(filepath):
        return []
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    segments = [s.strip() for s in content.split("~") if s.strip()]
    loops = []
    current_loop = None

    for seg in segments:
        parts = [p.strip() for p in seg.split("*")]
        tag = parts[0]
        if tag == "LX":
            current_loop = []
            loops.append(current_loop)
        elif tag in ("CTT", "SE", "GE", "IEA"):
