            return [unique_vals[0], primary_doc_name]
        else:
            return "CONFLICT"

    if fallback_dict is not None and fallback_doc_name is not None:
        fallback_vals = fallback_dict.get(part_id, [])
        if fallback_vals:
            unique_fb_vals = list(set(fallback_vals))
            if len(unique_fb_vals) == 1:
                return [unique_fb_vals[0], fallback_doc_name]
            else:
