```python
import sys
import os
import re
import json
from decimal import Decimal

MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
}

def parse_date(text):
    if not text:
        return None
    # Pattern 1: Month Day, Year
    m1 = re.search(r'\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b', text, re.IGNORECASE)
    if m1:
        month_str, day_str, year_str = m1.groups()
        month = MONTHS.get(month_str.lower()[:3])
        if month:
            return f"{int(year_str):04d}-{month:02d}-{int(day_str):02d}"

    # Pattern 2: Day Month Year
    m2 = re.search(r'\b(\d{1,2})(?:st|nd|rd|th)?\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?),?\s+(\d{4})\b', text, re.IGNORECASE)
    if m2:
        day_str, month_str, year_str = m2.groups()
        month = MONTHS.get(month_str.lower()[:3])
        if month:
            return f"{int(year_str):04d}-{month:02d}-{int(day_str):02d}"

    # Pattern 3: ISO format YYYY-MM-DD
    m3 = re.search(r'\b(\d{4})-(\d{2})-(\d{2})\b', text)
    if m3:
        return f"{int(m3.group(1)):04d}-{int(m3.group(2)):02d}-{int(m3.group(3)):02d}"

    return None

def format_amount(val_str):
    d = Decimal(val_str)
    if d == d.to_integral():
        return str(d.to_integral())
    return f"{d:f}".rstrip('0').rstrip('.')

def read_file(directory, doc_name):
    for filename in (f"{doc_name}.txt", doc_name):
        path = os.path.join(directory, filename)
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                return f.read()
    return ""

def parse_messages(file_content):
    raw_msgs = re.split(r'={10,}', file_content)
    messages = []
    for raw in raw_msgs:
        raw = raw.strip()
        if not raw or raw.startswith("MAILBOX EXPORT") or raw.startswith("Folder:"):
            continue
        parts = re.split(r'\n\s*\n', raw, maxsplit=1)
        if len(parts) == 2:
            headers, body = parts
        else:
            headers = parts[0]
            body = parts[0]

        entity_id = None
        for line in headers.splitlines():
            if line.lower().startswith('subject:'):
                m = re.search(r'-\s*([A-Za-z0-9]+(?:-[A-Za-z0-9]+)+)\s*$', line)
                if m:
                    entity_id = m.group(1).strip()
                    break
        if not entity_id:
            m = re.search(r'(?:Note on|For item|About)\s+([A-Za-z0-9-]+)', body, re.IGNORECASE)
            if m:
                entity_id = m.group(1).strip()
        if not entity_id:
            m = re.search(r'\b([A-Z]-\d+)\b', raw)
            if m:
                entity_id = m.group(1).strip()

        if entity_id:
            messages.append((entity_id, headers, body))
    return messages

# Fact extractors
def extract_cal_date(body):
    if re.search(r"\b(can't find|cannot find|could not find|no record|empty|unknown|unrecorded|gives no)\b", body, re.IGNORECASE):
        return None
    m = re.search(r'(?:sticker says|calibrated on|calibration(?:\s+date)?\s+is)\s+([^.\n]+)', body, re.IGNORECASE)
    if m:
        d = parse_date(m.group(1))
        if d:
            return d
    return parse_date(body)

def extract_test_date_test_reports(body):
    if re.search(r"\b(empty|unknown|unrecorded|no record|can't find|cannot find)\b", body, re.IGNORECASE):
        return None
    m = re.search(r'(?:test ran on|broke it on the frame on|ran on)\s+([^.\n]+)', body, re.IGNORECASE)
    if m:
        d = parse_date(m.group(1))
        if d:
            return d
    return parse_date(body)

def extract_test_date_lab_certs(body):
    if re.search(r"\b(empty|unknown|unrecorded|no record|can't find|cannot find)\b", body, re.IGNORECASE):
        return None
    m = re.search(r'(?:lab ran it on|test happened on|ran it on)\s+([^.\n]+)', body, re.IGNORECASE)
    if m:
        d = parse_date(m.group(1))
        if d:
            return d
    return parse_date(body)

def extract_measured_load_lab_certs(body):
    if re.search(r"\b(leaves (?:the )?failure load empty|load empty|no failure load|empty|unknown|unrecorded)\b", body, re.IGNORECASE):
        return None
    m = re.search(r'(?:certifies failure at|states it failed at|failure at)\s+([0-9.]+)\s*(?:kN|kilonewtons)', body, re.IGNORECASE)
    if m:
        return format_amount(m.group(1))
    return None

def extract_measured_load_test_reports(body):
    if re.search(r"\b(empty|unknown|unrecorded|no record)\b", body, re.IGNORECASE):
        return None
    m = re.search(r'(?:let go at|recorded failure at|failure at)\s+([0-9.]+)\s*(?:kN|kilonewtons)', body, re.IGNORECASE)
    if m:
        return format_amount(m.group(1))
    return None

def extract_specified_min_spec_sheets(body):
    if re.search(r"\b(gives no minimum|no minimum|empty|unknown|unrecorded)\b", body, re.IGNORECASE):
        return None
    m = re.search(r'(?:drawing minimum at failure is|calls for at least|minimum at failure is)\s+([0-9.]+)\s*(?:kN|kilonewtons)', body, re.IGNORECASE)
    if m:
        return format_amount(m.group(1))
    return None

def natural_sort_key(s):
    return [int(text) if text.isdigit() else text.lower() for text in re.split(r'(\d+)', s)]

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    directory = sys.argv[1]

    doc_names = ['calibration_log', 'lab_certificates', 'parts', 'spec_sheets', 'test_reports']
    parsed_docs = {}
    all_entities = set()

    for doc in doc_names:
        content = read_file(directory, doc)
        msgs = parse_messages(content)
        parsed_docs[doc] = msgs
        for ent, _, _ in msgs:
            all_entities.add(ent)

    def get_values(doc_name, entity, extractor):
        values = []
        for ent, _, body in parsed_docs.get(doc_name, []):
            if ent == entity:
                val = extractor(body)
                if val is not None:
                    values.append(val)
        return values

    def resolve_fact(entity, primary_doc, primary_extractor, fallback_doc=None, fallback_extractor=None):
        primary_vals = get_values(primary_doc, entity, primary_extractor)
        if primary_vals:
            unique_vals = list(dict.fromkeys(primary_vals))
            if len(unique_vals) > 1:
                return "CONFLICT"
            return [unique_vals[0], primary_doc]

        if fallback_doc and fallback_extractor:
            fallback_vals = get_values(fallback_doc, entity, fallback_extractor)
            if fallback_vals:
                unique_vals = list(dict.fromkeys(fallback_vals))
                if len(unique_vals) > 1:
                    return "CONFLICT"
                return [unique_vals[0], fallback_doc]

        return "ABSENT"

    sorted_entities = sorted(all_entities, key=natural_sort_key)
    output = {}

    for ent in sorted_entities:
        pair_id = f"ea.calibration_current::{ent}"
        output[pair_id] = {
            "calibration date": resolve_fact(ent, 'calibration_log', extract_cal_date),
            "test date": resolve_fact(ent, 'test_reports', extract_test_date_test_reports, 'lab_certificates', extract_test_date_lab_certs)
        }

    for ent in sorted_entities:
        pair_id = f"ea.load_with_margin::{ent}"
        output[pair_id] = {
            "measured load": resolve_fact(ent, 'lab_certificates', extract_measured_load_lab_certs, 'test_reports', extract_measured_load_test_reports),
