import os
import sys
import re
import json
from collections import defaultdict

MONTHS = {
    'jan': 1, 'january': 1,
    'feb': 2, 'february': 2,
    'mar': 3, 'march': 3,
    'apr': 4, 'april': 4,
    'may': 5,
    'jun': 6, 'june': 6,
    'jul': 7, 'july': 7,
    'aug': 8, 'august': 8,
    'sep': 9, 'september': 9,
    'oct': 10, 'october': 10,
    'nov': 11, 'november': 11,
    'dec': 12, 'december': 12,
}

def parse_date(text):
    if not text:
        return None
    # ISO: YYYY-MM-DD
    m = re.search(r'\b(\d{4})-(\d{1,2})-(\d{1,2})\b', text)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return f"{y:04d}-{mo:02d}-{d:02d}"

    # Day Month Year: e.g. 27th Jun 2026 or 4 Feb 2027
    m = re.search(r'\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+),?\s+(\d{4})\b', text)
    if m:
        mo_str = m.group(2).lower()
        if mo_str in MONTHS:
            d, mo, y = int(m.group(1)), MONTHS[mo_str], int(m.group(3))
            return f"{y:04d}-{mo:02d}-{d:02d}"

    # Month Day Year: e.g. March 2nd, 2026
    m = re.search(r'\b([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b', text)
    if m:
        mo_str = m.group(1).lower()
        if mo_str in MONTHS:
            mo, d, y = MONTHS[mo_str], int(m.group(2)), int(m.group(3))
            return f"{y:04d}-{mo:02d}-{d:02d}"

    return None

def normalize_amount(s):
    s = s.strip()
    if '.' in s:
        parts = s.split('.')
        int_part = parts[0] or '0'
        frac_part = parts[1].rstrip('0')
        if not frac_part:
            return str(int(int_part))
        else:
            return f"{int(int_part)}.{frac_part}"
    return str(int(s))

def read_file(dir_path, base_name):
    for name in [f"{base_name}.txt", base_name]:
        p = os.path.join(dir_path, name)
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                return f.read()
    return ""

def split_messages(content):
    messages = []
    parts = re.split(r'=+\r?\n', content)
    for part in parts:
        part = part.strip()
        if not part or part.startswith("MAILBOX EXPORT"):
            continue
        header_body = re.split(r'\r?\n\r?\n', part, maxsplit=1)
        headers = header_body[0]
        body = header_body[1] if len(header_body) > 1 else ""
        messages.append((headers, body, part))
    return messages

def get_message_entity(headers, body, part):
    sub_m = re.search(r'^Subject:.*?\b(P-\d+)\b', headers, re.MULTILINE)
    if sub_m:
        return sub_m.group(1)
    m = re.search(r'\b(P-\d+)\b', part)
    return m.group(1) if m else None

def parse_calibration_log(content):
    res = defaultdict(list)
    for headers, body, part in split_messages(content):
        entity = get_message_entity(headers, body, part)
        if not entity:
            continue
        if re.search(r"can't find|cannot find|isn't recorded|is not recorded|not recorded|no record", body, re.IGNORECASE):
            continue
        m = re.search(r'(?:calibrated on|sticker says)\s+([^.\n\r]+)', body, re.IGNORECASE)
        if m:
            d = parse_date(m.group(1))
            if d:
                res[entity].append(d)
        else:
            d = parse_date(body)
            if d:
                res[entity].append(d)
    return res

def parse_test_reports(content):
    dates = defaultdict(list)
    loads = defaultdict(list)
    for headers, body, part in split_messages(content):
        entity = get_message_entity(headers, body, part)
        if not entity:
            continue
        # Date
        has_date_negative = re.search(r"(?:date|day|time)\s*(?:isn't recorded|is not recorded|not recorded|can't find|cannot find)|can't find\s+the\s+.*?(?:date|day)", body, re.IGNORECASE)
        if not has_date_negative:
            m_date = re.search(r'(?:broke it on the frame on|break test ran on|tested on|test ran on)\s+([^.\n\r]+)', body, re.IGNORECASE)
            if m_date:
                d = parse_date(m_date.group(1))
                if d:
                    dates[entity].append(d)
        # Load
        m_load = re.search(r'(?:failure at|let go at|broke at|failed at)\s+([\d.]+)\s*(?:kN|kilonewtons)', body, re.IGNORECASE)
        if m_load:
            loads[entity].append(normalize_amount(m_load.group(1)))
    return dates, loads

def parse_lab_certificates(content):
    dates = defaultdict(list)
    loads = defaultdict(list)
    for headers, body, part in split_messages(content):
        entity = get_message_entity(headers, body, part)
        if not entity:
            continue
        # Date
        has_date_negative = re.search(r"(?:date|day)\s*(?:isn't recorded|is not recorded|not recorded)", body, re.IGNORECASE)
        if not has_date_negative:
            m_date = re.search(r'(?:lab test happened on|lab ran it on|test happened on|ran it on)\s+([^.\n\r]+)', body, re.IGNORECASE)
            if m_date:
                d = parse_date(m_date.group(1))
                if d:
                    dates[entity].append(d)
        # Load
        m_load = re.search(r'(?:failed at|failure at)\s+([\d.]+)\s*(?:kN|kilonewtons)', body, re.IGNORECASE)
        if m_load:
            loads[entity].append(normalize_amount(m_load.group(1)))
    return dates, loads

def parse_spec_sheets(content):
    loads = defaultdict(list)
    for headers, body, part in split_messages(content):
        entity = get_message_entity(headers, body, part)
        if not entity:
            continue
        m = re.search(r'(?:minimum at failure is|calls for at least|minimum is|requirement is)\s+([\d.]+)\s*(?:kN|kilonewtons)', body, re.IGNORECASE)
        if m:
            loads[entity].append(normalize_amount(m.group(1)))
    return loads

def resolve_fact(primary_doc, primary_vals, fallback_doc=None, fallback_vals=None):
    if primary_vals:
        distinct = sorted(list(set(primary_vals)))
        if len(distinct) == 1:
            return [distinct[0], primary_doc]
        else:
            return "CONFLICT"
    elif fallback_doc and fallback_vals:
        distinct = sorted(list(set(fallback_vals)))
        if len(distinct) == 1:
            return [distinct[0], fallback_doc]
        else:
            return "CONFLICT"
    else:
        return "ABSENT"

def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    calib_raw = read_file(dir_path, "calibration_log")
    test_raw = read_file(dir_path, "test_reports")
    lab_raw = read_file(dir_path, "lab_certificates")
    spec_raw = read_file(dir_path, "spec_sheets")
    parts_raw = read_file(dir_path, "parts")

    entities = set()
    for content in [calib_raw, test_raw, lab_raw, spec_raw, parts_raw]:
        for eid in re.findall(r'\bP-\d+\b', content):
            entities.add(eid)
    sorted_entities = sorted(list(entities))

    calib_dates = parse_calibration_log(calib_raw)
    test_dates, test_loads = parse_test_reports(test_raw)
    lab_dates, lab_loads = parse_lab_certificates(lab_raw)
    spec_loads = parse_spec_sheets(spec_raw)

    result = {}

    for eid in sorted_entities:
        pair_id = f"ea.calibration_current::{eid}"
        cal_date_val = resolve_fact("calibration_log", calib_dates.get(eid, []))
        test_date_val = resolve_fact("test_reports", test_dates.get(eid, []), "lab_certificates", lab_dates.get(eid, []))
        result[pair_id] = {
            "calibration date": cal_date_val,
            "test date": test_date_val
        }

    for eid in sorted_entities:
        pair_id = f"ea.load_with_margin::{eid}"
        meas_load_val = resolve_fact("lab_certificates", lab_loads.get(eid, []), "test_reports", test_loads.get(eid, []))
        spec_min_val = resolve_fact("spec_sheets", spec_loads.get(eid, []))
        result[pair_id] = {
            "measured load": meas_load_val,
            "specified minimum": spec_min_val
        }

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
