def parse_iso_week_date(val: str) -> str:
    val = val.strip()
    if "-W" in val:
        parts = val.split("-")
        year = int(parts[0])
        week = int(parts[1].lstrip("W"))
        day = int(parts[2])
        try:
            d = datetime.date.fromisocalendar(year, week, day)
        except AttributeError:
            jan4 = datetime.date(year, 1, 4)
            start_of_week1 = jan4 - datetime.timedelta(days=jan4.isoweekday() - 1)
            d = start_of_week1 + datetime.timedelta(weeks=week - 1, days=day - 1)
        return d.strftime("%Y-%m-%d")
    return val


def read_crosstab_tsv(filepath: str):
    rows = {}
    if not os.path.exists(filepath):
        return rows
    with open(filepath, "r", encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\r\n")
            if not line or line.startswith("#"):
                continue
            parts = line.split("\t")
            attr = parts[0].strip()
            values = [p.strip() for p in parts[1:]]
            rows[attr] = values
    return rows


def get_entity_values(doc_data, attr_name, entity_key):
    keys = doc_data.get("component.key", [])
    attr_vals = doc_data.get(attr_name, [])
    records = []
    for k, v in zip(keys, attr_vals):
        if k == entity_key and v not in ("~", ""):
            records.append(v)
    return records


def evaluate_doc(doc_data, attr_name, entity_key, fact_type):
    records = get_entity_values(doc_data, attr_name, entity_key)
    if not records:
        return "NONE", None

    if fact_type == "date":
        parsed = [parse_iso_week_date(r) for r in records]
        if len(set(parsed)) == 1:
            return "VALUE", parsed[0]
        else:
            return "CONFLICT", None
    elif fact_type == "amount":
        try:
            parsed_decimals = [Decimal(r) for r in records]
            if all(d == parsed_decimals[0] for d in parsed_decimals):
                if len(set(records)) == 1:
                    return "VALUE", records[0]
                else:
                    return "VALUE", str(parsed_decimals[0])
            else:
                return "CONFLICT", None
        except Exception:
            if len(set(records)) == 1:
                return "VALUE", records[0]
            else:
                return "CONFLICT", None

    return "NONE", None


def resolve_fact(docs, spec, entity_key):
    doc_primary = spec["doc_primary"]
    attr_primary = spec["attr_primary"]
    doc_fallback = spec["doc_fallback"]
    attr_fallback = spec["attr_fallback"]
    fact_type = spec["fact_type"]

    status, val = evaluate_doc(docs.get(doc_primary, {}), attr_primary, entity_key, fact_type)
    if status == "VALUE":
        return [val, doc_primary]
    elif status == "CONFLICT":
        return "CONFLICT"
    else:  # "NONE"
        if doc_fallback:
            status_fb, val_fb = evaluate_doc(docs.get(doc_fallback, {}), attr_fallback, entity_key, fact_type)
            if status_fb == "VALUE":
                return [val_fb, doc_fallback]
            elif status_fb == "CONFLICT":
                return "CONFLICT"
            else:
                return "ABSENT"
        else:
            return "ABSENT"


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    dir_path = sys.argv[1]

    doc_names = ["calibration_log", "lab_certificates", "parts", "spec_sheets", "test_reports"]
    docs = {}
    all_keys = set()
    for name in doc_names:
        file_path = os.path.join(dir_path, f"{name}.tsv")
        data = read_crosstab_tsv(file_path)
        docs[name] = data
        for k in data.get("component.key", []):
            if k:
                all_keys.add(k)

    # Determine pair list
    expected_default_keys = {p.split("::")[1] for p in PAIRS_LIST}
    if all_keys == expected_default_keys or not all_keys:
        pairs = PAIRS_LIST
    else:
        pairs = [
            f"{rule}::{k}"
            for rule in ["ea.calibration_current", "ea.load_with_margin"]
            for k in sorted(all_keys)
        ]

