import os
import re
import sys
import json
from datetime import date
from decimal import Decimal


def parse_crosstab_tsv(filepath):
    """
    Parses a cross-tab TSV where each row is an attribute,
    and each column after the first is a record.
    Returns a list of dicts: [{attr_name: value}, ...].
    """
    if not os.path.isfile(filepath):
        return []

    with open(filepath, 'r', encoding='utf-8') as f:
        lines = [line.strip('\r\n') for line in f if line.strip() and not line.startswith('#')]

    if not lines:
        return []

    header = lines[0].split('\t')
    num_records = len(header) - 1
    records = [{} for _ in range(num_records)]

    for line in lines[1:]:
        parts = line.split('\t')
        attr = parts[0].strip()
        vals = parts[1:]
        for i in range(num_records):
            val = vals[i].strip() if i < len(vals) else '~'
            records[i][attr] = val

    return records


def parse_date(val):
    if not val or val == '~':
        return None
    val = val.strip()
    m_wk = re.match(r'^(\d{4})-W(\d{2})-(\d)$', val)
    if m_wk:
        year, week, day = map(int, m_wk.groups())
        return date.fromisocalendar(year, week, day).strftime('%Y-%m-%d')
    m_iso = re.match(r'^\d{4}-\d{2}-\d{2}$', val)
    if m_iso:
        return val
    return val


def parse_amount(val):
    if not val or val == '~':
        return None
    val = val.strip()
    try:
        d = Decimal(val)
        if d == int(d):
            return str(int(d))
        s = str(d)
        if '.' in s:
            s = s.rstrip('0').rstrip('.')
        return s
    except Exception:
        return val


def get_fact_from_doc(records, entity_key, attr_name, parse_fn, doc_name):
    vals = set()
    for r in records:
        if r.get('component.key') == entity_key:
            raw_val = r.get(attr_name, '~')
            if raw_val and raw_val != '~':
                parsed = parse_fn(raw_val)
                if parsed is not None:
                    vals.add(parsed)
    if len(vals) == 0:
        return 'ABSENT', None, doc_name
    elif len(vals) == 1:
        return 'VALUE', list(vals)[0], doc_name
    else:
        return 'CONFLICT', None, doc_name


def resolve_fact(doc_specs, entity_key):
    for doc_name, records, attr_name, parse_fn in doc_specs:
        status, val, doc = get_fact_from_doc(records, entity_key, attr_name, parse_fn, doc_name)
        if status == 'CONFLICT':
            return 'CONFLICT'
        elif status == 'VALUE':
            return [val, doc]
        elif status == 'ABSENT':
            continue
    return 'ABSENT'


def load_doc(dir_path, name):
    tsv_path = os.path.join(dir_path, f"{name}.tsv")
    if os.path.isfile(tsv_path):
        return parse_crosstab_tsv(tsv_path)
    plain_path = os.path.join(dir_path, name)
    if os.path.isfile(plain_path):
        return parse_crosstab_tsv(plain_path)
    return []


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    dir_path = sys.argv[1]

    cal_log = load_doc(dir_path, 'calibration_log')
    lab_certs = load_doc(dir_path, 'lab_certificates')
    parts = load_doc(dir_path, 'parts')
    spec_sheets = load_doc(dir_path, 'spec_sheets')
    test_reports = load_doc(dir_path, 'test_reports')

    entities = set()
    for doc in [parts, spec_sheets, cal_log, lab_certs, test_reports]:
        for r in doc:
            k = r.get('component.key')
            if k and k != '~':
                entities.add(k)

    sorted_entities = sorted(entities)

    output = {}

    # Rule 1: ea.calibration_current
    for entity in sorted_entities:
        pair_id = f"ea.calibration_current::{entity}"
        cal_date = resolve_fact(
            [('calibration_log', cal_log, 'rig.cal.wk', parse_date)],
            entity
        )
        test_d = resolve_fact(
            [
                ('test_reports', test_reports, 'inhouse.break.wk', parse_date),
                ('lab_certificates', lab_certs, 'lab.break.wk', parse_date)
            ],
            entity
        )
        output[pair_id] = {
            "calibration date": cal_date,
            "test date": test_d
        }

    # Rule 2: ea.load_with_margin
    for entity in sorted_entities:
        pair_id = f"ea.load_with_margin::{entity}"
        meas_load = resolve_fact(
            [
                ('lab_certificates', lab_certs, 'lab.break.kn', parse_amount),
                ('test_reports', test_reports, 'inhouse.break.kn', parse_amount)
            ],
            entity
        )
        spec_min = resolve_fact(
            [('spec_sheets', spec_sheets, 'floor.force.kn', parse_amount)],
            entity
        )
        output[pair_id] = {
            "measured load": meas_load,
            "specified minimum": spec_min
        }

    print(json.dumps(output, indent=2))


if __name__ == '__main__':
    main()
