                continue
            parts = [p.strip() for p in line.split("|")]
            if header is None:
                header = parts
            else:
                row = {}
                for i, col in enumerate(header):
                    row[col] = parts[i] if i < len(parts) else ""
                rows.append(row)
    return rows

def parse_date(date_str):
    if not date_str or not date_str.strip():
        return None
    parts = date_str.strip().split("/")
    if len(parts) == 3:
        mm, dd, yyyy = parts
        return f"{int(yyyy):04d}-{int(mm):02d}-{int(dd):02d}"
    return date_str.strip()

def parse_force_to_kn(val_str, uom_str):
    if not val_str or not val_str.strip():
        return None
    try:
        val = Decimal(val_str.strip())
    except Exception:
        return None
    uom = uom_str.strip().upper() if uom_str else ""
    if uom == "KN":
        pass
    elif uom == "N":
        val = val / Decimal(1000)
    s = format(val, "f")
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return s

def get_values(rows, entity_key, value_getter):
    vals = set()
    for row in rows:
        if row.get("COMPONENT_CATALOG_KEY") == entity_key:
            v = value_getter(row)
            if v is not None and v != "":
                vals.add(v)
    return vals

def resolve_fact(first_doc_info, fallback_doc_info, entity_key):
    first_rows, first_name, first_getter = first_doc_info
    first_vals = get_values(first_rows, entity_key, first_getter)
    if len(first_vals) > 1:
        return "CONFLICT"
    elif len(first_vals) == 1:
        return [list(first_vals)[0], first_name]

    if fallback_doc_info is not None:
        fallback_rows, fallback_name, fallback_getter = fallback_doc_info
        fallback_vals = get_values(fallback_rows, entity_key, fallback_getter)
        if len(fallback_vals) > 1:
            return "CONFLICT"
        elif len(fallback_vals) == 1:
            return [list(fallback_vals)[0], fallback_name]

    return "ABSENT"

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    cal_log_rows = read_dsv(find_file(dir_path, "calibration_log"))
    test_rep_rows = read_dsv(find_file(dir_path, "test_reports"))
    lab_cert_rows = read_dsv(find_file(dir_path, "lab_certificates"))
    spec_sheet_rows = read_dsv(find_file(dir_path, "spec_sheets"))
    parts_rows = read_dsv(find_file(dir_path, "parts"))

    all_keys = set()
    for rows in [cal_log_rows, test_rep_rows, lab_cert_rows, spec_sheet_rows, parts_rows]:
        for r in rows:
            k = r.get("COMPONENT_CATALOG_KEY")
            if k:
                all_keys.add(k)

    prompt_keys = {p.split("::")[1] for p in PROMPT_PAIRS}
    if all_keys == prompt_keys:
        pairs = PROMPT_PAIRS
    else:
        sorted_keys = sorted(all_keys)
        pairs = [f"ea.calibration_current::{k}" for k in sorted_keys] + [
            f"ea.load_with_margin::{k}" for k in sorted_keys
        ]

    output = {}

    for pair in pairs:
        rule, entity_key = pair.split("::")
        if rule == "ea.calibration_current":
            cal_date = resolve_fact(
                (cal_log_rows, "calibration_log", lambda r: parse_date(r.get("LOAD_FRAME_CAL_DAY", ""))),
                None,
                entity_key,
            )
            t_date = resolve_fact(
                (test_rep_rows, "test_reports", lambda r: parse_date(r.get("INTERNAL_TRIAL_DAY", ""))),
                (lab_cert_rows, "lab_certificates", lambda r: parse_date(r.get("ACCREDITED_TRIAL_DAY", ""))),
                entity_key,
            )
            output[pair] = {
                "calibration date": cal_date,
                "test date": t_date,
            }
        elif rule == "ea.load_with_margin":
            m_load = resolve_fact(
                (
                    lab_cert_rows,
                    "lab_certificates",
                    lambda r: parse_force_to_kn(
                        r.get("ACCREDITED_ULTIMATE_FORCE", ""), r.get("ACCREDITED_ULTIMATE_FORCE_UOM", "")
                    ),
                ),
                (
                    test_rep_rows,
                    "test_reports",
                    lambda r: parse_force_to_kn(
                        r.get("INTERNAL_ULTIMATE_FORCE", ""), r.get("INTERNAL_ULTIMATE_FORCE_UOM", "")
                    ),
                ),
                entity_key,
            )
            s_min = resolve_fact(
                (
                    spec_sheet_rows,
                    "spec_sheets",
                    lambda r: parse_force_to_kn(
                        r.get("REQUIRED_ULTIMATE_FORCE", ""), r.get("REQUIRED_ULTIMATE_FORCE_UOM", "")
                    ),
                ),
                None,
                entity_key,
            )
            output[pair] = {
                "measured load": m_load,
                "specified minimum": s_min,
            }

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
